def compute_order_amount(age, pipeline, mu, cv, f, L):
    Q_MULT = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":6.0}
    LEAD_DEMAND_SCALE = 0.35 # OPT_PARAM: {"type":"float","initial":0.35,"min":0.0,"max":1.5}
    PROJECTED_CREDIT = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    RISK_CREDIT = 0.25 # OPT_PARAM: {"type":"float","initial":0.25,"min":0.0,"max":1.5}
    FIFO_FLOOR = 0.75 # OPT_PARAM: {"type":"float","initial":0.75,"min":0.0,"max":1.0}
    LIFO_FLOOR = 0.05 # OPT_PARAM: {"type":"float","initial":0.05,"min":0.0,"max":1.0}
    LIFO_AGE_POWER = 2.0 # OPT_PARAM: {"type":"float","initial":2.0,"min":0.2,"max":8.0}

    m = len(age)
    if m <= 0:
        return 0.0

    lead = int(L)
    if lead < 0:
        lead = 0

    fifo_share = float(f)
    if fifo_share < 0.0:
        fifo_share = 0.0
    if fifo_share > 1.0:
        fifo_share = 1.0

    work = [0.0] * m
    no_demand_work = [0.0] * m
    for i in range(m):
        value = float(age[i])
        if value < 0.0 or value != value:
            value = 0.0
        work[i] = value
        no_demand_work[i] = value

    fifo_demand = LEAD_DEMAND_SCALE * fifo_share * float(mu)
    lifo_demand = LEAD_DEMAND_SCALE * (1.0 - fifo_share) * float(mu)

    for t in range(lead):
        remaining = fifo_demand
        for i in range(m):
            available = work[i]
            if available <= remaining:
                work[i] = 0.0
                remaining = remaining - available
            else:
                work[i] = available - remaining
                remaining = 0.0

        remaining = lifo_demand
        for i in range(m - 1, -1, -1):
            available = work[i]
            if available <= remaining:
                work[i] = 0.0
                remaining = remaining - available
            else:
                work[i] = available - remaining
                remaining = 0.0

        shifted = [0.0] * m
        no_demand_shifted = [0.0] * m
        for i in range(m - 1):
            shifted[i] = work[i + 1]
            no_demand_shifted[i] = no_demand_work[i + 1]

        if t < lead - 1 and t < len(pipeline):
            arrival = float(pipeline[t])
            if arrival < 0.0 or arrival != arrival:
                arrival = 0.0
            shifted[m - 1] = arrival
            no_demand_shifted[m - 1] = arrival

        work = shifted
        no_demand_work = no_demand_shifted

    projected_credit = 0.0
    no_demand_credit = 0.0
    for i in range(m):
        relative_life = float(i + 1) / float(m)
        fifo_utility = FIFO_FLOOR + (1.0 - FIFO_FLOOR) * relative_life
        lifo_utility = LIFO_FLOOR + (1.0 - LIFO_FLOOR) * (relative_life ** LIFO_AGE_POWER)
        utility = fifo_share * fifo_utility + (1.0 - fifo_share) * lifo_utility
        projected_credit = projected_credit + utility * work[i]
        no_demand_credit = no_demand_credit + utility * no_demand_work[i]

    uncertain_credit = no_demand_credit - projected_credit
    if uncertain_credit < 0.0:
        uncertain_credit = 0.0

    raw_order = (
        Q_MULT * float(mu)
        - PROJECTED_CREDIT * projected_credit
        - RISK_CREDIT * uncertain_credit
    )

    if raw_order != raw_order or raw_order < 0.0:
        raw_order = 0.0
    if raw_order > 1000000.0:
        raw_order = 1000000.0

    return float(raw_order)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 18.0 # OPT_PARAM: {"type":"float","initial":18.0,"min":0.0,"max":60.0}
    projection_scale = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.5}
    age_power = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":10.0}
    inventory_credit = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}

    m = len(age)
    if m <= 0:
        return 0.0

    x = [0.0 for _ in range(m)]
    for i in range(m):
        value = float(age[i])
        if value < 0.0 or value != value:
            value = 0.0
        x[i] = value

    mf = f * mu
    ml = (1.0 - f) * mu
    demand_sd = mu * cv

    rf1 = 0.0
    rf2 = 0.0
    wf1 = 0.0
    if mf > 0.0:
        vf = f * demand_sd * demand_sd
        af = vf / (mf * mf) - 1.0 / mf
        if af < 1.0:
            af = 1.0
        rootf = (af * af - 1.0) ** 0.5
        bf = 1.0 + af + rootf
        cf = 1.0 + af - rootf
        wf1 = 1.0 / bf
        pf1 = 2.0 / (2.0 + mf * bf)
        pf2 = 2.0 / (2.0 + mf * cf)
        rf1 = 1.0 - pf1
        rf2 = 1.0 - pf2

    rl1 = 0.0
    rl2 = 0.0
    wl1 = 0.0
    if ml > 0.0:
        vl = (1.0 - f) * demand_sd * demand_sd
        al = vl / (ml * ml) - 1.0 / ml
        if al < 1.0:
            al = 1.0
        rootl = (al * al - 1.0) ** 0.5
        bl = 1.0 + al + rootl
        cl = 1.0 + al - rootl
        wl1 = 1.0 / bl
        pl1 = 2.0 / (2.0 + ml * bl)
        pl2 = 2.0 / (2.0 + ml * cl)
        rl1 = 1.0 - pl1
        rl2 = 1.0 - pl2

    lead = int(L)
    if lead < 0:
        lead = 0

    for t in range(lead):
        if mf > 0.0:
            rank = 0.0
            for i in range(m):
                amount = x[i]
                if amount > 0.0:
                    part1 = wf1 * (rf1 ** (rank + 1.0)) * (1.0 - rf1 ** amount) / (1.0 - rf1)
                    part2 = (1.0 - wf1) * (rf2 ** (rank + 1.0)) * (1.0 - rf2 ** amount) / (1.0 - rf2)
                    consumed = projection_scale * (part1 + part2)
                    if consumed < 0.0:
                        consumed = 0.0
                    if consumed > amount:
                        consumed = amount
                    x[i] = amount - consumed
                    rank = rank + amount

        if ml > 0.0:
            rank = 0.0
            for k in range(m):
                i = m - 1 - k
                amount = x[i]
                if amount > 0.0:
                    part1 = wl1 * (rl1 ** (rank + 1.0)) * (1.0 - rl1 ** amount) / (1.0 - rl1)
                    part2 = (1.0 - wl1) * (rl2 ** (rank + 1.0)) * (1.0 - rl2 ** amount) / (1.0 - rl2)
                    consumed = projection_scale * (part1 + part2)
                    if consumed < 0.0:
                        consumed = 0.0
                    if consumed > amount:
                        consumed = amount
                    x[i] = amount - consumed
                    rank = rank + amount

        shifted = [0.0 for _ in range(m)]
        for i in range(m - 1):
            shifted[i] = x[i + 1]

        incoming = 0.0
        if t < len(pipeline):
            incoming = float(pipeline[t])
            if incoming < 0.0 or incoming != incoming:
                incoming = 0.0
        shifted[m - 1] = incoming
        x = shifted

    effective_inventory = 0.0
    for i in range(m):
        remaining_fraction = float(i + 1) / float(m)
        weight = remaining_fraction ** age_power
        effective_inventory = effective_inventory + weight * x[i]

    order = S - inventory_credit * effective_inventory
    if order != order or order <= 0.0:
        return 0.0
    if order > 1000000.0:
        return 1000000.0
    return float(order)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    STOCH_MIX = 0.85 # OPT_PARAM: {"type":"float","initial":0.85,"min":0.0,"max":1.0}
    W_NEW = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    W_OLD = 1.3 # OPT_PARAM: {"type":"float","initial":1.3,"min":0.0,"max":3.0}
    AGE_POWER = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.2,"max":4.0}

    m = len(age)
    work = [0.0 for i in range(m)]
    for i in range(m):
        x = float(age[i])
        if x > 0.0 and x < 1000000000000.0:
            work[i] = x

    demand_scale = float(mu) * float(cv)
    means = [float(f) * float(mu), (1.0 - float(f)) * float(mu)]
    variances = [
        float(f) * demand_scale * demand_scale,
        (1.0 - float(f)) * demand_scale * demand_scale
    ]

    p1 = [1.0, 1.0]
    p2 = [1.0, 1.0]
    mix1 = [1.0, 1.0]

    for sidx in range(2):
        M = means[sidx]
        V = variances[sidx]
        if M > 0.0:
            a = V / (M * M) - 1.0 / M
            if a < 1.0:
                a = 1.0
            root = (a * a - 1.0) ** 0.5
            b = 1.0 + a + root
            c = 1.0 + a - root
            mix1[sidx] = 1.0 / b
            p1[sidx] = 2.0 / (2.0 + M * b)
            p2[sidx] = 2.0 / (2.0 + M * c)

    horizon = int(L)
    if horizon < 0:
        horizon = 0

    for t in range(horizon):
        if t > 0 and t - 1 < len(pipeline) and m > 0:
            arrival = float(pipeline[t - 1])
            if arrival > 0.0 and arrival < 1000000000000.0:
                work[m - 1] = work[m - 1] + arrival

        for sidx in range(2):
            M = means[sidx]
            if M > 0.0:
                r1 = 1.0 - p1[sidx]
                r2 = 1.0 - p2[sidx]
                w1 = mix1[sidx]
                w2 = 1.0 - w1
                cumulative = 0.0

                for k in range(m):
                    if sidx == 0:
                        i = k
                    else:
                        i = m - 1 - k

                    stock = work[i]
                    upper = cumulative + stock

                    e_lower = (
                        w1 * r1 * (1.0 - r1 ** cumulative) / p1[sidx]
                        + w2 * r2 * (1.0 - r2 ** cumulative) / p2[sidx]
                    )
                    e_upper = (
                        w1 * r1 * (1.0 - r1 ** upper) / p1[sidx]
                        + w2 * r2 * (1.0 - r2 ** upper) / p2[sidx]
                    )

                    if cumulative < M:
                        fluid_lower = cumulative
                    else:
                        fluid_lower = M
                    if upper < M:
                        fluid_upper = upper
                    else:
                        fluid_upper = M

                    blended_lower = (
                        STOCH_MIX * e_lower
                        + (1.0 - STOCH_MIX) * fluid_lower
                    )
                    blended_upper = (
                        STOCH_MIX * e_upper
                        + (1.0 - STOCH_MIX) * fluid_upper
                    )
                    used = blended_upper - blended_lower

                    if used < 0.0:
                        used = 0.0
                    if used > stock:
                        used = stock

                    work[i] = stock - used
                    cumulative = upper

        shifted = [0.0 for i in range(m)]
        for i in range(m - 1):
            shifted[i] = work[i + 1]
        work = shifted

    effective_inventory = 0.0
    if m <= 1:
        if m == 1:
            effective_inventory = W_NEW * work[0]
    else:
        denominator = float(m - 1)
        for i in range(m):
            shortness = float(m - 1 - i) / denominator
            weight = W_NEW + (W_OLD - W_NEW) * (shortness ** AGE_POWER)
            if weight < 0.0:
                weight = 0.0
            effective_inventory = effective_inventory + weight * work[i]

    order = S - effective_inventory
    if not (order == order):
        return 0.0
    if order <= 0.0:
        return 0.0
    if order > 1000000.0:
        return 1000000.0
    return float(order)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    CREDIT = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.4,"max":1.6}
    AGE_DISCOUNT = 0.35 # OPT_PARAM: {"type":"float","initial":0.35,"min":0.0,"max":1.5}
    TAIL_SCALE = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.35,"max":2.5}
    RISK = 0.0 # OPT_PARAM: {"type":"float","initial":0.0,"min":-3.0,"max":3.0}

    m = len(age)
    x = [float(age[i]) for i in range(m)]
    xv = [0.0 for i in range(m)]

    mf = f * mu
    ml = (1.0 - f) * mu
    demand_sd = mu * cv

    if mf > 0.0:
        vf = f * demand_sd * demand_sd
        af = vf / (mf * mf) - 1.0 / mf
        df = af * af - 1.0
        if df < 0.0:
            df = 0.0
        sf = df ** 0.5
        bf = 1.0 + af + sf
        cf = 1.0 + af - sf
        wf = 1.0 / bf
        rf1 = mf * bf / (2.0 + mf * bf)
        rf2 = mf * cf / (2.0 + mf * cf)
    else:
        wf = 0.0
        rf1 = 0.0
        rf2 = 0.0

    if ml > 0.0:
        vl = (1.0 - f) * demand_sd * demand_sd
        al = vl / (ml * ml) - 1.0 / ml
        dl = al * al - 1.0
        if dl < 0.0:
            dl = 0.0
        sl = dl ** 0.5
        bl = 1.0 + al + sl
        cl = 1.0 + al - sl
        wl = 1.0 / bl
        rl1 = ml * bl / (2.0 + ml * bl)
        rl2 = ml * cl / (2.0 + ml * cl)
    else:
        wl = 0.0
        rl1 = 0.0
        rl2 = 0.0

    lead = int(L)
    if lead < 0:
        lead = 0
    if lead > 10:
        lead = 10

    for step in range(lead):
        total = 0.0
        for i in range(m):
            if x[i] > 0.0:
                total = total + x[i]

        y = [0.0 for i in range(m)]
        yv = [0.0 for i in range(m)]
        prefix = 0.0

        if total > 0.0:
            for i in range(m):
                xi = x[i]
                if xi > 0.0:
                    nseg = int(xi)
                    if xi - float(nseg) > 0.000000001:
                        nseg = nseg + 1
                    if nseg < 1:
                        nseg = 1
                    if nseg > 80:
                        nseg = 80
                    width = xi / float(nseg)
                    local_mean = 0.0
                    local_var = 0.0

                    for h in range(nseg):
                        position = prefix + (float(h) + 0.5) * width
                        ef = (position + 0.5) / TAIL_SCALE
                        el = (total - position + 0.5) / TAIL_SCALE

                        if mf > 0.0:
                            pf = 1.0 - wf * (rf1 ** ef) - (1.0 - wf) * (rf2 ** ef)
                        else:
                            pf = 1.0

                        if ml > 0.0:
                            pl = 1.0 - wl * (rl1 ** el) - (1.0 - wl) * (rl2 ** el)
                        else:
                            pl = 1.0

                        if pf < 0.0:
                            pf = 0.0
                        if pf > 1.0:
                            pf = 1.0
                        if pl < 0.0:
                            pl = 0.0
                        if pl > 1.0:
                            pl = 1.0

                        ps = pf * pl
                        local_mean = local_mean + width * ps
                        local_var = local_var + width * ps * (1.0 - ps)

                    average_survival = local_mean / xi
                    y[i] = local_mean
                    yv[i] = local_var + xv[i] * average_survival * average_survival
                    prefix = prefix + xi

        next_x = [0.0 for i in range(m)]
        next_v = [0.0 for i in range(m)]
        for i in range(m - 1):
            next_x[i] = y[i + 1]
            next_v[i] = yv[i + 1]

        arrival = 0.0
        if step < len(pipeline):
            arrival = float(pipeline[step])
            if arrival < 0.0:
                arrival = 0.0
        if m > 0:
            next_x[m - 1] = arrival
            next_v[m - 1] = 0.0

        x = next_x
        xv = next_v

    credit = 0.0
    credit_variance = 0.0
    for i in range(m):
        freshness = float(i + 1) / float(m)
        weight = CREDIT * (1.0 - AGE_DISCOUNT * (1.0 - freshness))
        if weight < 0.0:
            weight = 0.0
        if weight > 2.5:
            weight = 2.5
        credit = credit + weight * x[i]
        credit_variance = credit_variance + weight * weight * xv[i]

    if credit_variance < 0.0:
        credit_variance = 0.0
    q = S - credit + RISK * (credit_variance ** 0.5)

    if q != q:
        q = 0.0
    if q < 0.0:
        q = 0.0
    if q > 1000000.0:
        q = 1000000.0
    return q

def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    W1 = 0.35 # OPT_PARAM: {"type":"float","initial":0.35,"min":0.0,"max":2.0}
    W2 = 0.60 # OPT_PARAM: {"type":"float","initial":0.60,"min":0.0,"max":2.0}
    W3 = 0.82 # OPT_PARAM: {"type":"float","initial":0.82,"min":0.0,"max":2.0}
    W4 = 1.00 # OPT_PARAM: {"type":"float","initial":1.00,"min":0.0,"max":2.0}
    KF = 1.00 # OPT_PARAM: {"type":"float","initial":1.00,"min":0.0,"max":2.0}
    KL = 1.00 # OPT_PARAM: {"type":"float","initial":1.00,"min":0.0,"max":2.0}

    m = len(age)
    x = [0.0] * m
    for i in range(m):
        v = float(age[i])
        if v < 0.0:
            v = 0.0
        x[i] = v

    if f > 0.0:
        MF = f * mu
        VF = f * (mu * cv) * (mu * cv)
        aF = VF / (MF * MF) - 1.0 / MF
        rootF = (aF * aF - 1.0) ** 0.5
        bF = 1.0 + aF + rootF
        cF = 1.0 + aF - rootF
        mixF = 1.0 / bF
        pF1 = 2.0 / (2.0 + MF * bF)
        pF2 = 2.0 / (2.0 + MF * cF)
        rF1 = 1.0 - pF1
        rF2 = 1.0 - pF2

    gL = 1.0 - f
    if gL > 0.0:
        ML = gL * mu
        VL = gL * (mu * cv) * (mu * cv)
        aL = VL / (ML * ML) - 1.0 / ML
        rootL = (aL * aL - 1.0) ** 0.5
        bL = 1.0 + aL + rootL
        cL = 1.0 + aL - rootL
        mixL = 1.0 / bL
        pL1 = 2.0 / (2.0 + ML * bL)
        pL2 = 2.0 / (2.0 + ML * cL)
        rL1 = 1.0 - pL1
        rL2 = 1.0 - pL2

    for t in range(L):
        if f > 0.0:
            y = [0.0] * m
            cumulative = 0.0
            previous_remaining = 0.0
            for i in range(m):
                cumulative = cumulative + x[i]
                if cumulative > 0.0:
                    truncated1 = rF1 * (1.0 - rF1 ** cumulative) / pF1
                    truncated2 = rF2 * (1.0 - rF2 ** cumulative) / pF2
                    remaining = cumulative - mixF * truncated1 - (1.0 - mixF) * truncated2
                    if remaining < 0.0:
                        remaining = 0.0
                    if remaining > cumulative:
                        remaining = cumulative
                else:
                    remaining = 0.0
                exact_cohort = remaining - previous_remaining
                calibrated = x[i] + KF * (exact_cohort - x[i])
                if calibrated < 0.0:
                    calibrated = 0.0
                if calibrated > x[i]:
                    calibrated = x[i]
                y[i] = calibrated
                previous_remaining = remaining
            x = y

        if gL > 0.0:
            y = [0.0] * m
            cumulative = 0.0
            previous_remaining = 0.0
            for k in range(m):
                i = m - 1 - k
                cumulative = cumulative + x[i]
                if cumulative > 0.0:
                    truncated1 = rL1 * (1.0 - rL1 ** cumulative) / pL1
                    truncated2 = rL2 * (1.0 - rL2 ** cumulative) / pL2
                    remaining = cumulative - mixL * truncated1 - (1.0 - mixL) * truncated2
                    if remaining < 0.0:
                        remaining = 0.0
                    if remaining > cumulative:
                        remaining = cumulative
                else:
                    remaining = 0.0
                exact_cohort = remaining - previous_remaining
                calibrated = x[i] + KL * (exact_cohort - x[i])
                if calibrated < 0.0:
                    calibrated = 0.0
                if calibrated > x[i]:
                    calibrated = x[i]
                y[i] = calibrated
                previous_remaining = remaining
            x = y

        for i in range(m - 1):
            x[i] = x[i + 1]
        if m > 0:
            x[m - 1] = 0.0
            if t < len(pipeline):
                arrival = float(pipeline[t])
                if arrival > 0.0:
                    x[m - 1] = arrival

    effective_inventory = 0.0
    for i in range(m):
        if i == 0:
            weight = W1
        elif i == 1:
            weight = W2
        elif i == 2:
            weight = W3
        else:
            weight = W4
        effective_inventory = effective_inventory + weight * x[i]

    q = S - effective_inventory
    if q != q:
        q = 0.0
    if q < 0.0:
        q = 0.0
    if q > 60.0:
        q = 60.0
    return float(q)
